ALL_SLIDES = [{'id': 1, 'title': 'Grouping Puzzles', 'tag': 'Let Us Think • Number Puzzles & Array Grouping', 'lecture': 'Welcome to our mathematics laboratory on The Dairy Farm! On a vibrant dairy farm, thousands of fresh buttermilk pouches, butter bricks, and milk cans are packed and dispatched every single morning. To handle this efficiently, dairy workers arrange items into neat rectangular crates and arrays. Mathematics begins with recognizing hidden patterns. Consider a logic puzzle where geometric shapes stand for secret numbers. If Circle multiplied by Circle equals 36, what must Circle be? Since 6 times 6 is 36, Circle must be 6. If Circle times Triangle equals 48, then 6 times Triangle is 48, revealing Triangle is 8! Next, look at buttermilk pouches packed in flat trays. If 4 trays each have 6 rows of 5 pouches, we compute 6 times 5 equals 30 pouches per tray, and 4 times 30 gives 120 pouches in total. We also explore digit placement challenges: choosing digits to make a product as close to 100 as possible. For example, 32 multiplied by 3 gives 96, which is only 4 away from 100! Multiplying arrays and cracking shape puzzles trains our mind to see multiplication as structured grouping.', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    At a dairy farm, goods are packed into orderly rows and columns. Multiplication provides the quickest tool to count structured arrays and solve algebraic shape puzzles.\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-emerald-500/30">\n                        <h4 class="font-bold text-emerald-400 mb-2 flex items-center gap-2">\n                            <span>🧩</span> Shape-Based Algebraic Puzzles\n                        </h4>\n                        <ul class="text-xs space-y-2 text-slate-300">\n                            <li>• If <strong>◯ × ◯ = 36</strong>, then <strong>◯ = 6</strong> (since 6 × 6 = 36).</li>\n                            <li>• If <strong>◯ × △ = 48</strong>, then <strong>6 × △ = 48</strong>, so <strong>△ = 8</strong>.</li>\n                            <li>• If <strong>△ × ▢ = 80</strong>, then <strong>8 × ▢ = 80</strong>, so <strong>▢ = 10</strong>.</li>\n                            <li>• Finding unknown values using inverse division: <strong>△ = 48 ÷ 6 = 8</strong>.</li>\n                        </ul>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-cyan-500/30">\n                        <h4 class="font-bold text-cyan-400 mb-2 flex items-center gap-2">\n                            <span>📦</span> Buttermilk Pouch Arrays\n                        </h4>\n                        <ul class="text-xs space-y-2 text-slate-300">\n                            <li>• <strong>1 Tray</strong>: 6 rows of 5 pouches = <strong>6 × 5 = 30 pouches</strong>.</li>\n                            <li>• <strong>4 Trays</strong>: 4 × 30 = <strong>120 total pouches</strong>.</li>\n                            <li>• <strong>Targeting 100</strong>: With digits 1, 2, 3, 4:\n                                <ul class="pl-4 mt-1 space-y-1">\n                                    <li>- 24 × 4 = 96 (difference of 4 from 100)</li>\n                                    <li>- 32 × 3 = 96 (difference of 4 from 100)</li>\n                                    <li>- 21 × 5 = 105 (difference of 5 from 100)</li>\n                                </ul>\n                            </li>\n                        </ul>\n                    </div>\n                </div>\n                <div class="p-3 bg-amber-950/40 border border-amber-500/30 rounded-lg text-xs text-amber-200">\n                    <strong>Key Insight:</strong> Multiplication represents repeated addition of equal groups: <em>Total = (Number of Groups) × (Items per Group)</em>.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_1', 'checkpoints': [{'question': 'If ▢ × ▢ = 49 and ▢ × ◯ = 35, what is the value of ◯?', 'options': ['5', '7', '6', '8'], 'correct': 0, 'explanation': 'Since ▢ × ▢ = 49, ▢ must be 7 (7 × 7 = 49). Substituting ▢ = 7 into 7 × ◯ = 35 gives ◯ = 35 ÷ 7 = 5.'}, {'question': 'A dairy worker packs 5 crates, each holding 8 rows with 6 bottles of milk. How many bottles are packed in total?', 'options': ['240 bottles', '48 bottles', '190 bottles', '300 bottles'], 'correct': 0, 'explanation': 'Each crate holds 8 × 6 = 48 bottles. For 5 crates, total bottles = 5 × 48 = 240 bottles.'}]}, {'id': 2, 'title': 'Multiplication Order', 'tag': 'Commutative Property • Zero & Identity Rules', 'lecture': 'Let us discover a fundamental rule of arithmetic: the order of numbers in multiplication does not change the result! Imagine a dairy farm where milk packets are organized. Suppose we have 3 boxes, and each box contains 2 packets of fresh milk. Total packets equal 3 times 2, which is 6. Now turn the crate sideways: we see 2 rows of 3 packets each! That is 2 times 3, which is also 6 packets. Whether we calculate 3 times 2 or 2 times 3, the total remains exactly 6! This universal truth is known as the Commutative Property of Multiplication. For any numbers, a times b equals b times a. This property is immensely helpful when multiplying three numbers: 4 times 5 times 7 can be grouped as 4 times 5 equals 20, and 20 times 7 equals 140. Or we can multiply 5 times 7 first to get 35, and 4 times 35 also equals 140! Finally, consider multiplying by zero. If a dairy has 5 crates but each crate is empty with 0 bottles, there are 5 times 0 equals 0 bottles. Any number multiplied by zero always yields zero!', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    The arrangement of items in rows and columns proves that the order of factors does not alter the product.\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-3 gap-3">\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-indigo-500/30">\n                        <h4 class="font-bold text-indigo-400 mb-2 flex items-center gap-1.5">\n                            <span>🔄</span> Commutative Rule\n                        </h4>\n                        <div class="text-xs space-y-1.5 text-slate-300">\n                            <p class="font-semibold text-emerald-300 text-sm">a × b = b × a</p>\n                            <p>• 3 crates of 2 bottles = 3 × 2 = <strong>6</strong></p>\n                            <p>• 2 crates of 3 bottles = 2 × 3 = <strong>6</strong></p>\n                            <p>• 15 × 8 = 8 × 15 = <strong>120</strong></p>\n                        </div>\n                    </div>\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-violet-500/30">\n                        <h4 class="font-bold text-violet-400 mb-2 flex items-center gap-1.5">\n                            <span>🔗</span> Associative Rule\n                        </h4>\n                        <div class="text-xs space-y-1.5 text-slate-300">\n                            <p class="font-semibold text-purple-300 text-sm">(a × b) × c = a × (b × c)</p>\n                            <p>• (4 × 5) × 7 = 20 × 7 = <strong>140</strong></p>\n                            <p>• 4 × (5 × 7) = 4 × 35 = <strong>140</strong></p>\n                            <p>• Choose groupings that yield friendly tens!</p>\n                        </div>\n                    </div>\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-rose-500/30">\n                        <h4 class="font-bold text-rose-400 mb-2 flex items-center gap-1.5">\n                            <span>⭕</span> Zero & Identity Rules\n                        </h4>\n                        <div class="text-xs space-y-1.5 text-slate-300">\n                            <p class="font-semibold text-amber-300 text-sm">a × 0 = 0 &nbsp;|&nbsp; a × 1 = a</p>\n                            <p>• 8 crates with 0 cans = 8 × 0 = <strong>0</strong></p>\n                            <p>• 0 crates of 15 cans = 0 × 15 = <strong>0</strong></p>\n                            <p>• 25 × 1 = <strong>25</strong> (Identity Element)</p>\n                        </div>\n                    </div>\n                </div>\n                <div class="p-3 bg-emerald-950/40 border border-emerald-500/30 rounded-lg text-xs text-emerald-200">\n                    <strong>Mental Math Strategy:</strong> When multiplying <strong>25 × 17 × 4</strong>, rearrange using the commutative property: <em>(25 × 4) × 17 = 100 × 17 = 1,700</em>.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_2', 'checkpoints': [{'question': 'Which mental rearrangement makes calculating 8 × 19 × 5 the fastest?', 'options': ['(8 × 5) × 19 = 40 × 19', '(8 × 19) × 5 = 152 × 5', '8 × (19 + 5) = 8 × 24', '(19 × 8) ÷ 5'], 'correct': 0, 'explanation': 'Multiplying 8 × 5 gives 40 (a friendly ten). Then 40 × 19 = 40 × (20 - 1) = 800 - 40 = 760, which is simple to compute mentally!'}, {'question': 'What is the value of 47 × 0 × 85?', 'options': ['0', '47', '85', '3,995'], 'correct': 0, 'explanation': 'By the Zero Property of Multiplication, any product containing 0 as a factor equals 0.'}]}, {'id': 3, 'title': 'Place Value Shifts', 'tag': 'Multiplying by 10, 100, and 1,000 • Zero Patterns', 'lecture': 'When a dairy farm expands deliveries from local families to city supermarkets, orders grow tenfold, a hundredfold, and a thousandfold! How does multiplying by powers of ten affect a number? In our base ten place value system, every step to the left is worth ten times more. When we multiply 25 cans of milk by 10, every digit shifts one place to the left: 2 tens become 2 hundreds, and 5 ones become 5 tens. An empty place appears in the units column, filled by a zero, giving 250! When we multiply 25 by 100, digits shift two places left, appending two zeros to give 2,500. Multiplying by 1,000 shifts digits three places left, appending three zeros to give 25,000! What if we multiply numbers like 60 by 400? We first multiply the non-zero leading digits: 6 times 4 equals 24. Then count the total zeros: one zero in 60 plus two zeros in 400 equals three zeros in all. Attaching three zeros gives 24,000! Tracking place value shifts makes multiplying by multiples of ten effortless.', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Multiplying by 10, 100, or 1,000 shifts every digit into a higher place-value column and places zero placeholders in the vacated positions.\n                </p>\n                <div class="overflow-x-auto">\n                    <table class="w-full text-xs text-left bg-slate-800/80 rounded-xl border border-slate-700">\n                        <thead class="bg-slate-700/60 text-emerald-300">\n                            <tr>\n                                <th class="p-2.5">Original</th>\n                                <th class="p-2.5">Multiplier</th>\n                                <th class="p-2.5">Place Value Shift</th>\n                                <th class="p-2.5">Product</th>\n                                <th class="p-2.5">Rule</th>\n                            </tr>\n                        </thead>\n                        <tbody class="divide-y divide-slate-700/60 text-slate-200">\n                            <tr>\n                                <td class="p-2 font-mono font-bold">34</td>\n                                <td class="p-2">× 10</td>\n                                <td class="p-2">1 place left (O → T, T → H)</td>\n                                <td class="p-2 font-mono font-bold text-amber-300">340</td>\n                                <td class="p-2">Append one 0</td>\n                            </tr>\n                            <tr>\n                                <td class="p-2 font-mono font-bold">34</td>\n                                <td class="p-2">× 100</td>\n                                <td class="p-2">2 places left (O → H, T → Th)</td>\n                                <td class="p-2 font-mono font-bold text-amber-300">3,400</td>\n                                <td class="p-2">Append two 0s</td>\n                            </tr>\n                            <tr>\n                                <td class="p-2 font-mono font-bold">34</td>\n                                <td class="p-2">× 1,000</td>\n                                <td class="p-2">3 places left (O → Th, T → TTh)</td>\n                                <td class="p-2 font-mono font-bold text-amber-300">34,000</td>\n                                <td class="p-2">Append three 0s</td>\n                            </tr>\n                            <tr>\n                                <td class="p-2 font-mono font-bold">70 × 800</td>\n                                <td class="p-2">Multiples of 10 & 100</td>\n                                <td class="p-2">(7 × 8) × (10 × 100)</td>\n                                <td class="p-2 font-mono font-bold text-cyan-300">56,000</td>\n                                <td class="p-2">7 × 8 = 56 + three 0s</td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n                <div class="p-3 bg-blue-950/40 border border-blue-500/30 rounded-lg text-xs text-blue-200">\n                    <strong>Trailing Zero Rule:</strong> When multiplying numbers with trailing zeros, multiply non-zero digits first, then count and append the sum of all trailing zeros.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_3', 'checkpoints': [{'question': 'What is the product of 500 × 60?', 'options': ['30,000', '3,000', '300,000', '300'], 'correct': 0, 'explanation': 'Multiply non-zero digits: 5 × 6 = 30. Then count zeros: 500 has two zeros, 60 has one zero (total 3 zeros). 30 with three zeros appended is 30,000.'}, {'question': 'A dairy cooperative sells 42 cans of ghee every day for 100 days. How many cans are sold in total?', 'options': ['4,200 cans', '420 cans', '42,000 cans', '8,400 cans'], 'correct': 0, 'explanation': '42 × 100 shifts the digits 4 and 2 two places to the left, appending two zeros: 4,200 cans.'}]}, {'id': 4, 'title': 'Mental Strategies', 'tag': 'Alternative Strategies • Student-Devised Methods', 'lecture': 'Mathematics is celebrated for offering multiple pathways to the exact same truth! Consider multiplying 18 by 5. In a dairy classroom, different students devised clever mental strategies. Student A uses the Halving and Doubling method: halve 18 to get 9, and double 5 to get 10; then 9 times 10 is effortlessly 90! Student B uses the Partitioning or Distributive method: split 18 into 10 plus 8; 10 times 5 is 50, and 8 times 5 is 40; adding 50 plus 40 gives 90! Student C uses the Compensation method: round 18 up to the friendly ten 20; 20 times 5 is 100; but since we took 2 extra groups of 5, we subtract 2 times 5, which is 10, leaving 100 minus 10 equals 90! Student D calculates 18 times 10 equals 180, and since 5 is half of 10, divides 180 by 2 to get 90. Notice how every method bypasses pencil-and-paper carrying. When we understand number properties, mental multiplication becomes fast, creative, and joyful!', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Compare the four brilliant student strategies to calculate <strong>18 × 5</strong> mentally:\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-3 text-xs">\n                    <div class="p-3 bg-slate-800/80 rounded-xl border border-teal-500/30">\n                        <span class="font-bold text-teal-400 block mb-1 text-sm">Method 1: Halving & Doubling</span>\n                        <p class="text-slate-300 mb-1.5">• Halve the even factor: 18 ÷ 2 = <strong>9</strong></p>\n                        <p class="text-slate-300 mb-1.5">• Double the other factor: 5 × 2 = <strong>10</strong></p>\n                        <p class="font-mono text-emerald-300 font-bold">• 9 × 10 = 90</p>\n                    </div>\n                    <div class="p-3 bg-slate-800/80 rounded-xl border border-cyan-500/30">\n                        <span class="font-bold text-cyan-400 block mb-1 text-sm">Method 2: Partitioning (Distributive)</span>\n                        <p class="text-slate-300 mb-1.5">• Split 18 into tens and ones: <strong>(10 + 8)</strong></p>\n                        <p class="text-slate-300 mb-1.5">• Multiply each part: (10 × 5) + (8 × 5)</p>\n                        <p class="font-mono text-emerald-300 font-bold">• 50 + 40 = 90</p>\n                    </div>\n                    <div class="p-3 bg-slate-800/80 rounded-xl border border-amber-500/30">\n                        <span class="font-bold text-amber-400 block mb-1 text-sm">Method 3: Compensation</span>\n                        <p class="text-slate-300 mb-1.5">• Round 18 to friendly 20: <strong>(20 × 5)</strong> = 100</p>\n                        <p class="text-slate-300 mb-1.5">• Subtract 2 extra groups of 5: 2 × 5 = <strong>10</strong></p>\n                        <p class="font-mono text-emerald-300 font-bold">• 100 - 10 = 90</p>\n                    </div>\n                    <div class="p-3 bg-slate-800/80 rounded-xl border border-purple-500/30">\n                        <span class="font-bold text-purple-400 block mb-1 text-sm">Method 4: Multiply by 10 & Halve</span>\n                        <p class="text-slate-300 mb-1.5">• Since 5 = 10 ÷ 2, multiply by 10 first: 18 × 10 = <strong>180</strong></p>\n                        <p class="text-slate-300 mb-1.5">• Take half of the result: 180 ÷ 2</p>\n                        <p class="font-mono text-emerald-300 font-bold">• 180 ÷ 2 = 90</p>\n                    </div>\n                </div>\n                <div class="p-3 bg-slate-800/80 border border-slate-600 rounded-lg text-xs text-slate-300">\n                    <strong>Rule of Flexibility:</strong> Choose the strategy that best exploits the special structure of the numbers involved!\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_4', 'checkpoints': [{'question': 'Using partitioning, what is the best way to compute 24 × 6 mentally?', 'options': ['(20 × 6) + (4 × 6) = 120 + 24 = 144', '(24 × 10) - (24 × 6) = 240 - 144', '(24 ÷ 6) × (6 ÷ 6) = 4', '(20 + 4) × (20 + 6)'], 'correct': 0, 'explanation': 'Partitioning 24 into 20 + 4 allows mental multiplication: 20 × 6 = 120 and 4 × 6 = 24; 120 + 24 = 144.'}, {'question': 'To calculate 36 × 5 by multiplying by 10 and halving, what are the steps?', 'options': ['36 × 10 = 360, then 360 ÷ 2 = 180', '36 ÷ 10 = 3.6, then 3.6 × 2 = 7.2', '36 × 2 = 72, then 72 × 10 = 720', '36 × 5 = 30 × 5 = 150'], 'correct': 0, 'explanation': 'Since 5 is half of 10, compute 36 × 10 = 360, then divide by 2: 360 ÷ 2 = 180.'}]}, {'id': 5, 'title': 'Doubling and Halving', 'tag': 'Area Models • Simplifying Multiplications with 5, 25, and 50', 'lecture': 'One of the most elegant geometric techniques in mathematics is the Doubling and Halving strategy. Picture a large rectangular pasture on the dairy farm that is 16 metres wide and 25 metres long. The total area is 16 times 25. Now imagine slicing the pasture right down the middle into two 8-metre strips. Take one 8-metre strip and paste it to the far end of the other strip! The width is now halved to 8 metres, but the length is doubled to 50 metres. The total area has not changed at all! We can halve and double again: halve 8 to 4, and double 50 to 100 metres! Now look at the calculation: 4 times 100 equals 400 square metres. Instead of struggling with 16 times 25, we simply multiplied 4 by 100! This strategy is especially powerful when multiplying by numbers ending in 5, 25, or 50. For 28 times 50: halve 28 to 14, double 50 to 100; 14 times 100 equals 1,400! In general, dividing one factor by 2 while multiplying the other by 2 keeps the total product perfectly preserved.', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Halving one factor while doubling the other leaves the area (product) completely invariant:\n                    <span class="font-mono text-emerald-300 font-bold">(a ÷ 2) × (b × 2) = a × b</span>.\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-3 gap-3 text-xs">\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-emerald-500/30">\n                        <h4 class="font-bold text-emerald-400 mb-1.5 text-sm">Multiplying by 5</h4>\n                        <p class="text-slate-300 mb-1">Halve even factor, double 5 to <strong>10</strong>:</p>\n                        <p class="font-mono text-slate-200">• 48 × 5</p>\n                        <p class="font-mono text-slate-200">• = (48 ÷ 2) × (5 × 2)</p>\n                        <p class="font-mono text-emerald-300 font-bold">• = 24 × 10 = 240</p>\n                    </div>\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-cyan-500/30">\n                        <h4 class="font-bold text-cyan-400 mb-1.5 text-sm">Multiplying by 25</h4>\n                        <p class="text-slate-300 mb-1">Halve twice (÷ 4), double 25 twice to <strong>100</strong>:</p>\n                        <p class="font-mono text-slate-200">• 36 × 25</p>\n                        <p class="font-mono text-slate-200">• = (36 ÷ 4) × (25 × 4)</p>\n                        <p class="font-mono text-cyan-300 font-bold">• = 9 × 100 = 900</p>\n                    </div>\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-amber-500/30">\n                        <h4 class="font-bold text-amber-400 mb-1.5 text-sm">Multiplying by 50</h4>\n                        <p class="text-slate-300 mb-1">Halve even factor, double 50 to <strong>100</strong>:</p>\n                        <p class="font-mono text-slate-200">• 46 × 50</p>\n                        <p class="font-mono text-slate-200">• = (46 ÷ 2) × (50 × 2)</p>\n                        <p class="font-mono text-amber-300 font-bold">• = 23 × 100 = 2,300</p>\n                    </div>\n                </div>\n                <div class="p-3 bg-violet-950/40 border border-violet-500/30 rounded-lg text-xs text-violet-200">\n                    <strong>Geometric Principle:</strong> Cutting a shape and rearranging its pieces preserves its total area. Slicing height in half and doubling width creates an identical area with friendly multiples of 10 or 100!\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_5', 'checkpoints': [{'question': 'Using the doubling and halving method, what is 24 × 25?', 'options': ['6 × 100 = 600', '12 × 50 = 700', '48 × 12.5 = 650', '24 × 100 = 2,400'], 'correct': 0, 'explanation': 'Halving 24 twice gives 24 ÷ 4 = 6. Doubling 25 twice gives 25 × 4 = 100. Thus 6 × 100 = 600.'}, {'question': 'Calculate 64 × 50 using doubling and halving:', 'options': ['3,200', '3,000', '3,400', '2,800'], 'correct': 0, 'explanation': 'Halve 64 to 32, double 50 to 100. Then 32 × 100 = 3,200.'}]}, {'id': 6, 'title': 'Nearest Multiple', 'tag': 'Compensation Strategy • Adjusting Over-Counting & Under-Counting', 'lecture': 'What if a factor is not a round multiple of ten, but sits just one or two units away? For example, consider multiplying 4 by 19. A dairy van delivers 4 cartons, with 19 bottles of toned milk in each carton. 19 is difficult to multiply directly in your head, but 20 is remarkably easy! Imagine each carton had 20 bottles. Then 4 times 20 equals 80 bottles. But wait! We added 1 extra bottle per carton, so across 4 cartons we over-counted by 4 times 1, which is 4 bottles. To compensate, we subtract that extra 4 from 80: 80 minus 4 equals 76 bottles! This is the Nearest Multiple Compensation Strategy. Let us test it on 6 times 29: round 29 to 30; 6 times 30 is 180; subtract 6 times 1, leaving 180 minus 6 equals 174! What if a number is just above a multiple of ten, such as 5 times 42? Round down to 40: 5 times 40 is 200; then add the extra 5 times 2, which is 10, giving 200 plus 10 equals 210! By rounding to the nearest ten and adjusting the difference, tricky numbers become swift mental calculations.', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    The compensation strategy rounds a factor to the nearest friendly ten, multiplies, and compensates for over- or under-counting.\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-rose-500/30">\n                        <h4 class="font-bold text-rose-400 mb-2 flex items-center gap-2">\n                            <span>🔻</span> Over-Counting Adjustment (Subtract)\n                        </h4>\n                        <p class="text-slate-300 mb-2">When a factor ends in 8 or 9, round UP to the nearest ten and subtract the excess:</p>\n                        <div class="space-y-2 font-mono text-slate-200 bg-slate-900/60 p-2.5 rounded-lg">\n                            <p><strong>4 × 19:</strong> 4 × (20 - 1) = (4 × 20) - (4 × 1) = 80 - 4 = <span class="text-emerald-400 font-bold">76</span></p>\n                            <p><strong>7 × 39:</strong> 7 × (40 - 1) = (7 × 40) - (7 × 1) = 280 - 7 = <span class="text-emerald-400 font-bold">273</span></p>\n                            <p><strong>6 × 48:</strong> 6 × (50 - 2) = (6 × 50) - (6 × 2) = 300 - 12 = <span class="text-emerald-400 font-bold">288</span></p>\n                        </div>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-teal-500/30">\n                        <h4 class="font-bold text-teal-400 mb-2 flex items-center gap-2">\n                            <span>🔺</span> Under-Counting Adjustment (Add)\n                        </h4>\n                        <p class="text-slate-300 mb-2">When a factor ends in 1 or 2, round DOWN to the nearest ten and add the remainder:</p>\n                        <div class="space-y-2 font-mono text-slate-200 bg-slate-900/60 p-2.5 rounded-lg">\n                            <p><strong>5 × 42:</strong> 5 × (40 + 2) = (5 × 40) + (5 × 2) = 200 + 10 = <span class="text-teal-400 font-bold">210</span></p>\n                            <p><strong>8 × 31:</strong> 8 × (30 + 1) = (8 × 30) + (8 × 1) = 240 + 8 = <span class="text-teal-400 font-bold">248</span></p>\n                            <p><strong>9 × 62:</strong> 9 × (60 + 2) = (9 × 60) + (9 × 2) = 540 + 18 = <span class="text-teal-400 font-bold">558</span></p>\n                        </div>\n                    </div>\n                </div>\n                <div class="p-3 bg-amber-950/40 border border-amber-500/30 rounded-lg text-xs text-amber-200">\n                    <strong>General Algebraic Form:</strong> <em>k × (N ± d) = (k × N) ± (k × d)</em> (The Distributive Law over Addition and Subtraction).\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_6', 'checkpoints': [{'question': 'What is 8 × 49 using the nearest multiple compensation strategy?', 'options': ['(8 × 50) - 8 = 400 - 8 = 392', '(8 × 40) + 9 = 320 + 9 = 329', '(8 × 50) + 8 = 408', '(8 × 45) + 4 = 364'], 'correct': 0, 'explanation': '49 is 50 - 1. So 8 × 49 = 8 × (50 - 1) = (8 × 50) - (8 × 1) = 400 - 8 = 392.'}, {'question': 'Calculate 6 × 52 using the under-counting adjustment strategy:', 'options': ['312', '300', '320', '292'], 'correct': 0, 'explanation': '6 × 52 = 6 × (50 + 2) = (6 × 50) + (6 × 2) = 300 + 12 = 312.'}]}, {'id': 7, 'title': 'Application Problems', 'tag': 'Let Us Solve • Word Problems in Real-World Contexts', 'lecture': "Multiplication is the engine of daily commerce, agriculture, and construction. Let us visit the village dairy and community centre to solve real-world problems. First, in the village auditorium where dairy cooperative meetings take place, there are 24 rows of chairs, and each row has 18 chairs. How many people can attend? Using partitioning: 24 times 18 equals 24 times 20 minus 24 times 2; 480 minus 48 equals 432 seats! Next, consider the dairy farm's prize herd of 14 Sahiwal cows. If each cow yields an average of 12 litres of milk every day, how much milk is collected daily? 14 times 12: 14 times 10 is 140, plus 14 times 2 is 28, giving 168 litres every day! In a week of 7 days, the herd produces 7 times 168: 7 times 100 is 700, 7 times 60 is 420, and 7 times 8 is 56; summing these gives 1,176 litres! Finally, the cooperative tailors uniform kurtas for its 8 dairy staff. Each kurta requires 2 metres 25 centimetres of cloth. 8 times 2 metres is 16 metres, and 8 times 25 centimetres is 200 centimetres, which is exactly 2 metres. Total cloth required is 18 metres!", 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Step-by-step mathematical reasoning transforms word descriptions into clean multiplicative models:\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-3 gap-3 text-xs">\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-indigo-500/30">\n                        <h4 class="font-bold text-indigo-400 mb-1.5 flex items-center gap-1.5">\n                            <span>🪑</span> Auditorium Seating\n                        </h4>\n                        <p class="text-slate-300">• 24 rows with 18 seats each</p>\n                        <p class="text-slate-300 font-mono">• 24 × 18 = 24 × (20 - 2)</p>\n                        <p class="text-slate-300 font-mono">• = 480 - 48</p>\n                        <p class="font-mono text-emerald-300 font-bold text-sm mt-1">• = 432 seats</p>\n                    </div>\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-cyan-500/30">\n                        <h4 class="font-bold text-cyan-400 mb-1.5 flex items-center gap-1.5">\n                            <span>🥛</span> Herd Milk Production\n                        </h4>\n                        <p class="text-slate-300">• 14 cows × 12 L/day</p>\n                        <p class="text-slate-300 font-mono">• Daily = 14 × 12 = 168 L</p>\n                        <p class="text-slate-300 font-mono">• 7 days = 168 × 7</p>\n                        <p class="font-mono text-cyan-300 font-bold text-sm mt-1">• = 1,176 litres/week</p>\n                    </div>\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-amber-500/30">\n                        <h4 class="font-bold text-amber-400 mb-1.5 flex items-center gap-1.5">\n                            <span>🧵</span> Uniform Kurta Fabric\n                        </h4>\n                        <p class="text-slate-300">• 8 kurtas × 2 m 25 cm</p>\n                        <p class="text-slate-300 font-mono">• Metres: 8 × 2 m = 16 m</p>\n                        <p class="text-slate-300 font-mono">• Centimetres: 8 × 25 cm = 200 cm = 2 m</p>\n                        <p class="font-mono text-amber-300 font-bold text-sm mt-1">• Total = 18 metres</p>\n                    </div>\n                </div>\n                <div class="p-3 bg-emerald-950/40 border border-emerald-500/30 rounded-lg text-xs text-emerald-200">\n                    <strong>Problem-Solving Heuristic:</strong> Identify the <em>Rate per Unit</em> (e.g., litres per cow, metres per garment) and multiply by the <em>Number of Units</em>.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_7', 'checkpoints': [{'question': 'A dairy worker packs 15 boxes of cheese blocks. If each box contains 24 blocks, how many blocks are packed in total?', 'options': ['360 blocks', '340 blocks', '380 blocks', '300 blocks'], 'correct': 0, 'explanation': '15 × 24 = 15 × (20 + 4) = 300 + 60 = 360 blocks.'}, {'question': 'A jogging track around the dairy farm pasture is 450 metres long. If Kabir jogs 8 full laps every morning, what total distance does he cover?', 'options': ['3,600 metres (3.6 km)', '3,200 metres', '4,000 metres', '3,800 metres'], 'correct': 0, 'explanation': '8 × 450 m = 8 × (400 + 50) = 3,200 + 400 = 3,600 m = 3.6 km.'}]}, {'id': 8, 'title': 'Compost Savings', 'tag': 'Waste and Composting • Ecological Arithmetic & Household Savings', 'lecture': 'At the dairy farm, sustainability and mathematics go hand in hand! Cows produce dung, and dairy households generate organic vegetable peels and kitchen waste. Instead of discarding this waste into landfills, the farm converts it into nutrient-rich organic compost. Let us examine the numbers. A typical dairy family produces 350 grams of organic kitchen waste each day. How much waste is generated in a 30-day month? 350 multiplied by 30: 35 times 3 is 105, plus two zeros gives 10,500 grams, which is 10.5 kilograms! Over a full year of 365 days, Kanti and John calculate the waste generated. Kanti breaks 365 into 300 plus 60 plus 5 and multiplies each by 350 grams: 350 times 300 is 105,000 grams; 350 times 60 is 21,000 grams; and 350 times 5 is 1,750 grams. Summing these gives 127,750 grams, which is over 127 kilograms of waste! When turned into compost, the family saves money. If a 5-kilogram bag of commercial compost costs 120 rupees, producing 25 bags of homemade compost saves 25 times 120 rupees. 25 times 100 is 2,500, and 25 times 20 is 500; total savings equal 3,000 rupees a year!', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Ecological arithmetic proves how converting organic waste into compost creates environmental health and substantial household financial savings.\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-emerald-500/30">\n                        <h4 class="font-bold text-emerald-400 mb-2 flex items-center gap-2">\n                            <span>🌱</span> Kitchen Waste Computation\n                        </h4>\n                        <p class="text-slate-300 mb-1">• Daily household organic waste: <strong>350 g</strong></p>\n                        <p class="text-slate-300 mb-1">• In 1 Month (30 days): 350 × 30 = <strong>10,500 g = 10.5 kg</strong></p>\n                        <p class="text-slate-300 mb-1">• In 1 Year (365 days) via Kanti\'s expansion:</p>\n                        <div class="pl-3 py-1 font-mono text-slate-200 space-y-0.5 border-l-2 border-emerald-500/40">\n                            <p>350 × 300 = 105,000 g</p>\n                            <p>350 × 60 = 21,000 g</p>\n                            <p>350 × 5 = 1,750 g</p>\n                            <p class="text-emerald-300 font-bold">Sum = 127,750 g = 127.75 kg</p>\n                        </div>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-amber-500/30">\n                        <h4 class="font-bold text-amber-400 mb-2 flex items-center gap-2">\n                            <span>💰</span> Financial Compost Savings\n                        </h4>\n                        <p class="text-slate-300 mb-1">• Home Compost Produced: <strong>25 bags (5 kg each)</strong></p>\n                        <p class="text-slate-300 mb-1">• Market price of 1 commercial bag: <strong>₹ 120</strong></p>\n                        <p class="text-slate-300 mb-1">• Annual Savings = 25 × ₹ 120:</p>\n                        <div class="pl-3 py-1 font-mono text-slate-200 space-y-0.5 border-l-2 border-amber-500/40">\n                            <p>25 × 100 = ₹ 2,500</p>\n                            <p>25 × 20 = ₹ 500</p>\n                            <p class="text-amber-300 font-bold">Total Annual Savings = ₹ 3,000</p>\n                        </div>\n                        <p class="mt-2 text-slate-400 italic">Zero waste to landfill + ₹ 3,000 retained in family budget!</p>\n                    </div>\n                </div>\n                <div class="p-3 bg-emerald-950/40 border border-emerald-500/30 rounded-lg text-xs text-emerald-200">\n                    <strong>Green Mathematics:</strong> Math enables communities to quantify waste reduction, energy conservation, and ecological savings with exact precision.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_8', 'checkpoints': [{'question': 'If a dairy school canteen produces 450 g of food scraps daily, how much waste is generated in 20 days?', 'options': ['9,000 g (9 kg)', '8,000 g', '900 g', '90,000 g'], 'correct': 0, 'explanation': '450 × 20 = 45 × 2 × 100 = 90 × 100 = 9,000 g = 9 kg.'}, {'question': 'A village cooperative makes 40 bags of vermicompost. If each bag saves ₹ 150 compared to chemical fertilizer, what are the total savings?', 'options': ['₹ 6,000', '₹ 5,500', '₹ 6,500', '₹ 4,000'], 'correct': 0, 'explanation': '40 × ₹ 150 = 4 × 15 × 100 = 60 × 100 = ₹ 6,000.'}]}, {'id': 9, 'title': 'Expanded Methods', 'tag': "Let Us Multiply • Nida's and John's Box & Grid Algorithms", 'lecture': "When multiplying larger multi-digit numbers, breaking numbers apart by place value ensures no cross-multiplication is missed. In the dairy farm accounts office, students learn Nida's and John's expanded grid methods. Suppose we need to multiply 69 by 45 to calculate the cost of 45 feed sacks priced at 69 rupees each. First, decompose both numbers into tens and ones: 69 becomes 60 plus 9, and 45 becomes 40 plus 5. Draw a two-by-two grid with four rectangular cells. In cell one, multiply 60 by 40: 6 times 4 is 24, plus two zeros gives 2,400. In cell two, multiply 9 by 40 to get 360. In cell three, multiply 60 by 5 to get 300. In cell four, multiply 9 by 5 to get 45. Now sum these four partial products! Add the top row: 2,400 plus 360 equals 2,760. Add the bottom row: 300 plus 45 equals 345. Finally, combine the two rows: 2,760 plus 345 gives 3,105 rupees! John's box method provides complete visual clarity, guaranteeing that every single place-value interaction is accurately tracked before final addition.", 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    The expanded box/grid method decomposes multi-digit factors by place value, computing individual partial products before summing them.\n                </p>\n                <div class="bg-slate-800/80 p-4 rounded-xl border border-cyan-500/30">\n                    <h4 class="font-bold text-cyan-400 mb-2 flex items-center justify-between">\n                        <span>📦 Calculating 69 × 45 via 2×2 Partial Product Grid</span>\n                        <span class="text-xs font-mono bg-cyan-950 px-2 py-0.5 rounded text-cyan-300">69 = 60 + 9 | 45 = 40 + 5</span>\n                    </h4>\n                    <div class="grid grid-cols-3 gap-2 text-center text-xs font-mono my-3 max-w-md mx-auto">\n                        <div class="p-2 bg-slate-900/60 rounded font-bold text-slate-400 flex items-center justify-center">×</div>\n                        <div class="p-2 bg-indigo-900/40 rounded font-bold text-indigo-300 border border-indigo-500/30">60</div>\n                        <div class="p-2 bg-indigo-900/40 rounded font-bold text-indigo-300 border border-indigo-500/30">9</div>\n\n                        <div class="p-2 bg-emerald-900/40 rounded font-bold text-emerald-300 border border-emerald-500/30 flex items-center justify-center">40</div>\n                        <div class="p-3 bg-slate-900/80 rounded border border-slate-700">\n                            <span class="text-slate-400 block text-[10px]">60 × 40</span>\n                            <span class="text-amber-300 font-bold text-sm">2,400</span>\n                        </div>\n                        <div class="p-3 bg-slate-900/80 rounded border border-slate-700">\n                            <span class="text-slate-400 block text-[10px]">9 × 40</span>\n                            <span class="text-amber-300 font-bold text-sm">360</span>\n                        </div>\n\n                        <div class="p-2 bg-emerald-900/40 rounded font-bold text-emerald-300 border border-emerald-500/30 flex items-center justify-center">5</div>\n                        <div class="p-3 bg-slate-900/80 rounded border border-slate-700">\n                            <span class="text-slate-400 block text-[10px]">60 × 5</span>\n                            <span class="text-amber-300 font-bold text-sm">300</span>\n                        </div>\n                        <div class="p-3 bg-slate-900/80 rounded border border-slate-700">\n                            <span class="text-slate-400 block text-[10px]">9 × 5</span>\n                            <span class="text-amber-300 font-bold text-sm">45</span>\n                        </div>\n                    </div>\n                    <div class="flex flex-wrap items-center justify-center gap-3 text-xs font-mono pt-2 border-t border-slate-700">\n                        <span>Row 1: 2,400 + 360 = <strong>2,760</strong></span>\n                        <span class="text-slate-500">+</span>\n                        <span>Row 2: 300 + 45 = <strong>345</strong></span>\n                        <span class="text-slate-500">=</span>\n                        <span class="text-emerald-400 font-bold text-sm bg-emerald-950/60 px-3 py-1 rounded-lg border border-emerald-500/40">Total: 3,105</span>\n                    </div>\n                </div>\n                <div class="p-3 bg-emerald-950/40 border border-emerald-500/30 rounded-lg text-xs text-emerald-200">\n                    <strong>Algorithmic Guarantee:</strong> Decomposing into <em>(a + b) × (c + d) = ac + ad + bc + bd</em> prevents place-value omission errors.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_9', 'checkpoints': [{'question': 'In the box multiplication of 48 × 35, what are the four partial products?', 'options': ['1,200, 240, 200, 40', '1,200, 240, 200, 50', '1,400, 200, 200, 40', '1,200, 280, 160, 40'], 'correct': 0, 'explanation': '48 = 40 + 8 and 35 = 30 + 5. The partial products are: 40 × 30 = 1,200; 8 × 30 = 240; 40 × 5 = 200; 8 × 5 = 40. Sum = 1,200 + 240 + 200 + 40 = 1,680.'}, {'question': "What is 32 × 8 using Nida's expanded method?", 'options': ['(30 × 8) + (2 × 8) = 240 + 16 = 256', '(30 × 8) + (2 × 8) = 240 + 8 = 248', '(30 + 2) × (8 + 8) = 32 × 16 = 512', '240 - 16 = 224'], 'correct': 0, 'explanation': '32 = 30 + 2. Multiply each part by 8: (30 × 8) = 240, (2 × 8) = 16. Sum = 240 + 16 = 256.'}]}, {'id': 10, 'title': 'Everyday Arithmetic', 'tag': 'Let Us Do • Cinema Seating, Cricket Statistics & Bulk Procurement', 'lecture': 'Everyday life presents rich scenarios where multi-step arithmetic guides decisions. Consider a cricket match attended by the dairy village youth club. A star batter plays a magnificent innings consisting of 14 boundaries of 4 runs each, 8 towering sixes, and 32 singles ran between the wickets. Let us compute her total score: 14 boundaries times 4 runs equals 56 runs; 8 sixes times 6 runs equals 48 runs; and 32 singles times 1 run equals 32 runs. Adding them together: 56 plus 48 is 104, and 104 plus 32 gives 136 total runs scored! Next, let us visit the district cinema hall, which features 28 rows with 35 seats in every row. How many tickets can be sold for a houseful show? 28 times 35: using doubling and halving, halve 28 to 14 and double 35 to 70; then 14 times 70 equals 980 seats! Finally, in the grain market, the cooperative purchases 45 bags of cattle feed at 620 rupees per bag. 45 times 600 is 27,000, and 45 times 20 is 900; total cost is 27,900 rupees! Mathematics empowers us to tally, manage, and verify real transactions instantly.', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Composite arithmetic problems require calculating sub-products for distinct categories and combining them into a final total:\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-3 gap-3 text-xs">\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-amber-500/30">\n                        <h4 class="font-bold text-amber-400 mb-1.5 flex items-center gap-1.5">\n                            <span>🏏</span> Cricket Match Breakdown\n                        </h4>\n                        <p class="text-slate-300">• 14 Fours: 14 × 4 = <strong>56 runs</strong></p>\n                        <p class="text-slate-300">• 8 Sixes: 8 × 6 = <strong>48 runs</strong></p>\n                        <p class="text-slate-300">• 32 Singles: 32 × 1 = <strong>32 runs</strong></p>\n                        <p class="font-mono text-amber-300 font-bold text-sm mt-1 pt-1 border-t border-slate-700">Total = 136 runs</p>\n                    </div>\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-indigo-500/30">\n                        <h4 class="font-bold text-indigo-400 mb-1.5 flex items-center gap-1.5">\n                            <span>🎬</span> Cinema Seating Capacity\n                        </h4>\n                        <p class="text-slate-300">• 28 rows × 35 seats/row</p>\n                        <p class="text-slate-300 font-mono">• Doubling & Halving:</p>\n                        <p class="text-slate-300 font-mono">• = 14 × 70</p>\n                        <p class="font-mono text-indigo-300 font-bold text-sm mt-1 pt-1 border-t border-slate-700">Total = 980 seats</p>\n                    </div>\n                    <div class="bg-slate-800/80 p-3.5 rounded-xl border border-emerald-500/30">\n                        <h4 class="font-bold text-emerald-400 mb-1.5 flex items-center gap-1.5">\n                            <span>🌾</span> Cattle Feed Procurement\n                        </h4>\n                        <p class="text-slate-300">• 45 bags × ₹ 620/bag</p>\n                        <p class="text-slate-300 font-mono">• 45 × 600 = ₹ 27,000</p>\n                        <p class="text-slate-300 font-mono">• 45 × 20 = ₹ 900</p>\n                        <p class="font-mono text-emerald-300 font-bold text-sm mt-1 pt-1 border-t border-slate-700">Total = ₹ 27,900</p>\n                    </div>\n                </div>\n                <div class="p-3 bg-slate-800/80 border border-slate-600 rounded-lg text-xs text-slate-300">\n                    <strong>Multi-Step Checklist:</strong> 1. Segment the problem into clear categories. 2. Multiply unit rates by quantities. 3. Sum the partial components.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_10', 'checkpoints': [{'question': 'A school library has 16 cupboards, each with 5 shelves, and each shelf contains 25 books. How many books are there in total?', 'options': ['2,000 books', '1,800 books', '2,400 books', '1,600 books'], 'correct': 0, 'explanation': 'Total books = 16 × 5 × 25. Grouping: 16 × (5 × 25) = 16 × 125, or (16 × 5) × 25 = 80 × 25. 80 × 25 = (80 ÷ 4) × (25 × 4) = 20 × 100 = 2,000 books!'}, {'question': 'A village merchant sells 35 bags of basmati rice at ₹ 840 per bag. What is the total sale value?', 'options': ['₹ 29,400', '₹ 28,400', '₹ 30,200', '₹ 26,800'], 'correct': 0, 'explanation': '35 × 840 = 35 × (800 + 40) = (35 × 800) + (35 × 40) = 28,000 + 1,400 = ₹ 29,400.'}]}, {'id': 11, 'title': 'Dairy Cooperative', 'tag': 'Advanced Column Multiplication • Multi-Digit Standard Algorithm', 'lecture': "Now let us examine the crown jewel of written arithmetic: the standard vertical column multiplication algorithm, used by accountants at the dairy cooperative. Mili's father manages milk collection from 453 high-yielding indigenous Gir cows. If each cow produces an average of 13 litres of milk in a day, how many litres does the cooperative collect? We set up 453 multiplied by 13 vertically. Step one: multiply 453 by the 3 units: 3 times 3 is 9; 3 times 5 tens is 15 tens, write 5 and carry 1; 3 times 4 hundreds is 12 hundreds plus 1 carry is 13 hundreds. The first partial product is 1,359. Step two: multiply 453 by the 1 in the tens place, which has a value of 10. Crucially, place a zero in the units column as a place holder! Then 1 times 453 gives 4,530. Step three: add the two partial products: 1,359 plus 4,530 equals 5,889 litres of milk! For three-digit by three-digit numbers, such as 574 tins of ghee sold at 125 rupees each, we generate three partial products: multiplying by 5 ones, by 2 tens (20), and by 1 hundred (100). Adding 2,870 plus 11,480 plus 57,400 yields 71,750 rupees. Mastering column multiplication empowers us to handle numbers of any magnitude!", 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    The standard column algorithm streamlines multi-digit multiplication by recording unit carries and aligning partial products using place-value zeros.\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-indigo-500/30">\n                        <h4 class="font-bold text-indigo-400 mb-2 font-mono">Gir Cow Milk: 453 × 13</h4>\n                        <div class="font-mono text-sm space-y-1 bg-slate-900/60 p-3 rounded-lg">\n                            <p class="text-right text-slate-400">453</p>\n                            <p class="text-right text-slate-400">× &nbsp;13</p>\n                            <div class="border-b border-slate-600 my-1"></div>\n                            <p class="text-right text-cyan-300">1359 &nbsp;<span class="text-[10px] text-slate-400">(453 × 3)</span></p>\n                            <p class="text-right text-amber-300">+ 4530 &nbsp;<span class="text-[10px] text-slate-400">(453 × 10)</span></p>\n                            <div class="border-b border-slate-600 my-1"></div>\n                            <p class="text-right text-emerald-400 font-bold text-base">5889</p>\n                        </div>\n                        <p class="text-[11px] text-slate-300 mt-2">• Place value zero in 4,530 is mandatory because 1 represents 1 Ten (10)!</p>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-violet-500/30">\n                        <h4 class="font-bold text-violet-400 mb-2 font-mono">Ghee Sales: 574 × 125</h4>\n                        <div class="font-mono text-xs space-y-1 bg-slate-900/60 p-3 rounded-lg">\n                            <p class="text-right text-slate-400">574</p>\n                            <p class="text-right text-slate-400">× 125</p>\n                            <div class="border-b border-slate-600 my-1"></div>\n                            <p class="text-right text-cyan-300">2870 &nbsp;<span class="text-[10px] text-slate-400">(574 × 5)</span></p>\n                            <p class="text-right text-amber-300">11480 &nbsp;<span class="text-[10px] text-slate-400">(574 × 20)</span></p>\n                            <p class="text-right text-purple-300">+ 57400 &nbsp;<span class="text-[10px] text-slate-400">(574 × 100)</span></p>\n                            <div class="border-b border-slate-600 my-1"></div>\n                            <p class="text-right text-emerald-400 font-bold text-sm">71750</p>\n                        </div>\n                        <p class="text-[11px] text-slate-300 mt-2">• 3-digit multiplier generates 3 partial products aligned with 0, 1, and 2 zeros.</p>\n                    </div>\n                </div>\n                <div class="p-3 bg-blue-950/40 border border-blue-500/30 rounded-lg text-xs text-blue-200">\n                    <strong>The Zero Invariant:</strong> When multiplying by the tens digit, append one zero; by the hundreds digit, append two zeros; by the thousands digit, append three zeros.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_11', 'checkpoints': [{'question': 'What is the product of 324 × 26 using the standard column algorithm?', 'options': ['8,424', '7,824', '8,224', '8,624'], 'correct': 0, 'explanation': 'First partial product: 324 × 6 = 1,944. Second partial product: 324 × 20 = 6,480. Sum = 1,944 + 6,480 = 8,424.'}, {'question': 'In the multiplication of 615 × 42, why do we write 24,600 as the second partial product?', 'options': ['Because 4 is in the tens place, so we are multiplying 615 by 40', 'Because 615 × 4 = 2,460 and we add a random zero', 'Because we must always round numbers to the hundreds', 'Because the product must end with 00'], 'correct': 0, 'explanation': 'The digit 4 in 42 has a place value of 40 (4 tens). 615 × 40 = 24,600.'}]}, {'id': 12, 'title': 'Error Analysis', 'tag': 'Check, Check! • Diagnosing Common Computational Bugs', 'lecture': "A true mathematician is not just someone who solves problems, but someone who can inspect mathematical work, spot mistakes, and explain why they happened. In our 'Check, Check!' clinic, students analyze common errors in multiplication. Let us look at the most famous bug: The Missing Zero Trap. Suppose a student multiplies 54 by 23. In the first line, 54 times 3 gives 162. In the second line, the student multiplies 54 by 2 and writes 108 directly beneath 162 without shifting! Adding 162 plus 108 gives 270. Is 270 reasonable? Quick estimation: 50 times 20 is 1,000! How could 54 times 23 be only 270? The mistake is clear: the student multiplied by 2 instead of 20! The second line should be 1,080, giving 162 plus 1,080 equals 1,242. Another common trap is Premature Carry Addition: when multiplying 47 by 3, a student multiplies 3 times 7 to get 21, writes 1 and carries 2; then adds the carried 2 to 4 to make 6, and multiplies 3 times 6 to get 18, writing 181! That is wrong: you must multiply first: 3 times 4 is 12, then add the carried 2 to get 14, giving 141. By checking place values and estimating products, we safeguard our work against errors.", 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Diagnosing computational errors reveals the underlying structure of algorithms and strengthens mathematical rigor:\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-rose-500/30">\n                        <h4 class="font-bold text-rose-400 mb-2 flex items-center gap-2">\n                            <span>❌</span> Trap 1: The Missing Zero Placeholder\n                        </h4>\n                        <div class="font-mono bg-slate-900/60 p-2.5 rounded-lg space-y-1 mb-2">\n                            <p class="text-slate-400">54 × 23</p>\n                            <p class="text-slate-300">&nbsp; 162 &nbsp;<span class="text-emerald-400">✓ (54 × 3)</span></p>\n                            <p class="text-rose-400 font-bold">+ 108 &nbsp;❌ Missing tens zero!</p>\n                            <p class="text-slate-400">-----</p>\n                            <p class="text-rose-400 font-bold">&nbsp; 270 &nbsp;❌ Nonsensical (50 × 20 = 1,000!)</p>\n                        </div>\n                        <p class="text-emerald-300 font-semibold">• Correction: Second row must be <strong>1,080</strong> (54 × 20). Correct sum = <strong>1,242</strong>.</p>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-amber-500/30">\n                        <h4 class="font-bold text-amber-400 mb-2 flex items-center gap-2">\n                            <span>❌</span> Trap 2: Premature Carry Addition\n                        </h4>\n                        <div class="font-mono bg-slate-900/60 p-2.5 rounded-lg space-y-1 mb-2">\n                            <p class="text-slate-400">47 × 3 (carry 2 from 3 × 7 = 21)</p>\n                            <p class="text-rose-400 font-bold">• Wrong: (4 + 2) × 3 = 6 × 3 = 18 → 181 ❌</p>\n                            <p class="text-emerald-300 font-bold">• Right: (4 × 3) + 2 = 12 + 2 = 14 → 141 ✓</p>\n                        </div>\n                        <p class="text-slate-300">• Always multiply the place value first, then add the carried amount!</p>\n                    </div>\n                </div>\n                <div class="p-3 bg-amber-950/40 border border-amber-500/30 rounded-lg text-xs text-amber-200">\n                    <strong>Sanity Check Heuristic:</strong> Before finalizing any multi-digit product, perform a quick <em>Rough Estimate</em> by rounding both numbers to their highest place value.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_12', 'checkpoints': [{'question': 'A student calculates 38 × 42 and gets 304. By rough estimation, why is this answer impossible?', 'options': ['38 is near 40 and 42 is near 40, so 40 × 40 = 1,600; 304 is far too small', 'Because 38 × 42 must be an odd number', 'Because 38 × 42 must end with 8', 'Because 38 + 42 = 80'], 'correct': 0, 'explanation': 'Rough estimation: 40 × 40 = 1,600. An answer of 304 means the student forgot the tens place value zero in the second partial product (actual product is 1,596).'}, {'question': 'In the multiplication 65 × 14, the student writes partial products 260 and 65, getting 325. What was the exact error?', 'options': ['Wrote 65 instead of 650 (failed to multiply by 10)', 'Multiplied 65 by 4 incorrectly', 'Subtracted instead of adding partial products', 'Forgot to carry 2'], 'correct': 0, 'explanation': 'In 65 × 14, the 1 represents 10. The second partial product should be 65 × 10 = 650, not 65. The correct answer is 260 + 650 = 910.'}]}, {'id': 13, 'title': 'Derivative Facts', 'tag': 'Flexible Strategies • Fact Family Derivations & Special Endings', 'lecture': "Suppose an accountant discovers that 17 times 23 equals 391. Do you need to set up a long column calculation to find 17 times 46? Absolutely not! Look closely at the numbers: 46 is exactly double 23. Therefore, 17 times 46 must be exactly double 391! 391 doubled is 782. What about 34 times 23? Here, 34 is double 17, while 23 stays unchanged. So 34 times 23 is also 391 times 2, which equals 782! What about 17 times 24? 24 is just one more group of 17 than 23! So simply add 17 to 391: 391 plus 17 equals 408. What about 17 times 22? Subtract one group of 17: 391 minus 17 equals 374! Knowing a single anchor fact unlocks a whole constellation of derivative facts. We also exploit numbers ending in 25, 75, or 125: since 25 is 100 divided by 4, 32 times 25 is 32 divided by 4 times 100, which is 8 times 100 equals 800. Since 125 is 1,000 divided by 8, 48 times 125 is 48 divided by 8 times 1,000, which is 6,000! Flexible thinking turns complex facts into child's play.", 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    A single known multiplication fact serves as a powerful anchor to derive neighboring and scaled products algebraically:\n                </p>\n                <div class="bg-slate-800/80 p-4 rounded-xl border border-teal-500/30">\n                    <h4 class="font-bold text-teal-400 mb-3 text-center">\n                        Anchor Fact: <span class="font-mono text-amber-300 text-base bg-slate-900/80 px-3 py-1 rounded-lg border border-amber-500/30">17 × 23 = 391</span>\n                    </h4>\n                    <div class="grid grid-cols-2 md:grid-cols-4 gap-2.5 text-xs font-mono text-center">\n                        <div class="p-2.5 bg-slate-900/60 rounded-lg border border-slate-700">\n                            <span class="text-slate-400 block text-[10px]">Double Factor 2</span>\n                            <span class="font-bold text-slate-200">17 × 46</span>\n                            <span class="text-emerald-400 block font-bold text-sm mt-1">391 × 2 = 782</span>\n                        </div>\n                        <div class="p-2.5 bg-slate-900/60 rounded-lg border border-slate-700">\n                            <span class="text-slate-400 block text-[10px]">Double Factor 1</span>\n                            <span class="font-bold text-slate-200">34 × 23</span>\n                            <span class="text-emerald-400 block font-bold text-sm mt-1">391 × 2 = 782</span>\n                        </div>\n                        <div class="p-2.5 bg-slate-900/60 rounded-lg border border-slate-700">\n                            <span class="text-slate-400 block text-[10px]">+1 Group of 17</span>\n                            <span class="font-bold text-slate-200">17 × 24</span>\n                            <span class="text-cyan-400 block font-bold text-sm mt-1">391 + 17 = 408</span>\n                        </div>\n                        <div class="p-2.5 bg-slate-900/60 rounded-lg border border-slate-700">\n                            <span class="text-slate-400 block text-[10px]">-1 Group of 17</span>\n                            <span class="font-bold text-slate-200">17 × 22</span>\n                            <span class="text-cyan-400 block font-bold text-sm mt-1">391 - 17 = 374</span>\n                        </div>\n                    </div>\n                </div>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-3 text-xs">\n                    <div class="bg-slate-800/80 p-3 rounded-xl border border-indigo-500/30">\n                        <h4 class="font-bold text-indigo-400 mb-1">Shortcut for × 25</h4>\n                        <p class="text-slate-300">• Since 25 = 100 ÷ 4, divide factor by 4 and append two 0s:</p>\n                        <p class="font-mono text-emerald-300 font-bold mt-1">• 44 × 25 = (44 ÷ 4) × 100 = 11 × 100 = 1,100</p>\n                    </div>\n                    <div class="bg-slate-800/80 p-3 rounded-xl border border-purple-500/30">\n                        <h4 class="font-bold text-purple-400 mb-1">Shortcut for × 125</h4>\n                        <p class="text-slate-300">• Since 125 = 1,000 ÷ 8, divide factor by 8 and append three 0s:</p>\n                        <p class="font-mono text-purple-300 font-bold mt-1">• 56 × 125 = (56 ÷ 8) × 1,000 = 7 × 1,000 = 7,000</p>\n                    </div>\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_13', 'checkpoints': [{'question': 'Given that 19 × 21 = 399, what is 19 × 22 without performing full multiplication?', 'options': ['399 + 19 = 418', '399 + 21 = 420', '399 × 2 = 798', '399 + 1 = 400'], 'correct': 0, 'explanation': '19 × 22 is one more group of 19 than 19 × 21. Therefore, 399 + 19 = 418.'}, {'question': 'Compute 64 × 125 using the fractional power shortcut:', 'options': ['8,000', '7,800', '8,200', '6,400'], 'correct': 0, 'explanation': '125 = 1,000 ÷ 8. So 64 × 125 = (64 ÷ 8) × 1,000 = 8 × 1,000 = 8,000.'}]}, {'id': 14, 'title': "King's Reward", 'tag': "The King's Reward • Exponential Growth Puzzle", 'lecture': 'Prepare to be astonished by the sheer power of repeated multiplication! In an ancient kingdom, a clever dairy farmer solved a royal crisis and was offered a reward by the king for seven days. The king gave three options. Choice A: Receive a handsome flat sum of 100,000 gold coins every single day. Over seven days, that equals 7 times 100,000, which is 700,000 gold coins. Choice B: Receive 2 coins on day one, and have the amount double each day! On day one, 2 coins; day two, 4; day three, 8; day four, 16; day five, 32; day six, 64; and day seven, 128 coins. The total is only 254 coins. Choice C: Start with just 1 coin on day one, but multiply the daily amount by 5 every single day! Day one gives 1 coin; day two gives 5; day three gives 25; day four gives 125; day five gives 625; day six gives 3,125; and on day seven, gives 15,625 coins! The total for seven days is 19,531 coins. While Choice A wins for seven days, see what happens if the reward continues for just ten days! Under Choice C, day eight is 78,125; day nine is 390,625; and day ten is nearly two million coins! Repeated multiplication expands with explosive, unstoppable speed.', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Comparing linear addition against exponential multiplication reveals how multiplicative growth rapidly overtakes additive amounts over time:\n                </p>\n                <div class="overflow-x-auto">\n                    <table class="w-full text-xs text-left bg-slate-800/80 rounded-xl border border-slate-700">\n                        <thead class="bg-slate-700/60 text-emerald-300">\n                            <tr>\n                                <th class="p-2">Day</th>\n                                <th class="p-2">Choice A (₹ 100k Daily)</th>\n                                <th class="p-2">Choice B (Doubling × 2)</th>\n                                <th class="p-2">Choice C (Quintupling × 5)</th>\n                            </tr>\n                        </thead>\n                        <tbody class="divide-y divide-slate-700/60 text-slate-200 font-mono">\n                            <tr>\n                                <td class="p-1.5 font-bold">Day 1</td>\n                                <td class="p-1.5">100,000</td>\n                                <td class="p-1.5">2</td>\n                                <td class="p-1.5 text-amber-300">1</td>\n                            </tr>\n                            <tr>\n                                <td class="p-1.5 font-bold">Day 3</td>\n                                <td class="p-1.5">100,000</td>\n                                <td class="p-1.5">8</td>\n                                <td class="p-1.5 text-amber-300">25</td>\n                            </tr>\n                            <tr>\n                                <td class="p-1.5 font-bold">Day 5</td>\n                                <td class="p-1.5">100,000</td>\n                                <td class="p-1.5">32</td>\n                                <td class="p-1.5 text-amber-300">625</td>\n                            </tr>\n                            <tr>\n                                <td class="p-1.5 font-bold">Day 7</td>\n                                <td class="p-1.5">100,000</td>\n                                <td class="p-1.5">128</td>\n                                <td class="p-1.5 text-amber-300 font-bold">15,625</td>\n                            </tr>\n                            <tr class="bg-slate-900/60 font-bold">\n                                <td class="p-2 text-emerald-400">7-Day Total</td>\n                                <td class="p-2 text-emerald-400">₹ 700,000 (Winner for 7 days)</td>\n                                <td class="p-2 text-slate-400">₹ 254</td>\n                                <td class="p-2 text-amber-400">₹ 19,531</td>\n                            </tr>\n                            <tr class="bg-emerald-950/40 font-bold">\n                                <td class="p-2 text-cyan-300">Day 10 Single Day</td>\n                                <td class="p-2 text-slate-400">₹ 100,000</td>\n                                <td class="p-2 text-slate-400">₹ 1,024</td>\n                                <td class="p-2 text-cyan-300">₹ 1,953,125 (Multiplication explodes!)</td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n                <div class="p-3 bg-amber-950/40 border border-amber-500/30 rounded-lg text-xs text-amber-200">\n                    <strong>Exponential Insight:</strong> While addition adds constant amounts, multiplication scales the existing quantity by a factor, compounding into astronomical figures.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_14', 'checkpoints': [{'question': 'In Choice B, if day 1 is 2 coins and it doubles each day, how many coins are received on Day 6?', 'options': ['64 coins', '32 coins', '128 coins', '12 coins'], 'correct': 0, 'explanation': 'Day 1 = 2; Day 2 = 4; Day 3 = 8; Day 4 = 16; Day 5 = 32; Day 6 = 64 coins.'}, {'question': 'In Choice C (multiplying by 5 daily), how many coins are received on Day 5 starting with 1 coin on Day 1?', 'options': ['625 coins', '125 coins', '3,125 coins', '25 coins'], 'correct': 0, 'explanation': 'Day 1 = 1; Day 2 = 5; Day 3 = 25; Day 4 = 125; Day 5 = 125 × 5 = 625 coins.'}]}, {'id': 15, 'title': 'Number Patterns', 'tag': 'Multiplication Patterns • Palindromic Mountains & Grid Extremes', 'lecture': 'Mathematics is the study of visual and numerical harmony. When we multiply special sequences, breathtaking patterns emerge. Consider multiplying numbers composed only of the digit 1, known as repunits. Look at this symmetry: 1 times 1 is 1. 11 times 11 is 121. 111 times 111 is 12,321. 1,111 times 1,111 is 1,234,321! The digits count up to the number of ones in the factor, then count symmetrically back down to 1. They form a numerical palindrome, reading identically forwards and backwards! Next, examine the famous pattern multiplying sequences by 9 and adding consecutive numbers: 1 times 9 plus 2 equals 11; 12 times 9 plus 3 equals 111; 123 times 9 plus 4 equals 1,111; and 1,234 times 9 plus 5 equals 11,111! Finally, on a 100-number grid, what adjacent pair produces the highest product? The pair with the highest magnitudes: 99 times 100 equals 9,900. When comparing pairs that have the exact same sum, the product is always greatest when the two numbers are as close to each other as possible. Pattern recognition lets us predict products without calculation.', 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Discover the fascinating mathematical architecture behind palindromic repunits, digit staircases, and number grid boundaries:\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs font-mono">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-indigo-500/30">\n                        <h4 class="font-bold text-indigo-400 mb-2 font-sans flex items-center gap-1.5">\n                            <span>🏔️</span> Repunit Palindrome Mountains\n                        </h4>\n                        <div class="space-y-1 bg-slate-900/60 p-3 rounded-lg text-slate-200">\n                            <p>1 × 1 = <span class="text-emerald-400 font-bold">1</span></p>\n                            <p>11 × 11 = <span class="text-emerald-400 font-bold">121</span></p>\n                            <p>111 × 111 = <span class="text-emerald-400 font-bold">12321</span></p>\n                            <p>1111 × 1111 = <span class="text-emerald-400 font-bold">1234321</span></p>\n                            <p>11111 × 11111 = <span class="text-emerald-400 font-bold">123454321</span></p>\n                        </div>\n                        <p class="text-[11px] text-slate-400 font-sans mt-2">The peak digit equals the number of ones in each factor!</p>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-violet-500/30">\n                        <h4 class="font-bold text-violet-400 mb-2 font-sans flex items-center gap-1.5">\n                            <span>🪜</span> The 9s Staircase of Ones\n                        </h4>\n                        <div class="space-y-1 bg-slate-900/60 p-3 rounded-lg text-slate-200">\n                            <p>1 × 9 + 2 = <span class="text-amber-400 font-bold">11</span></p>\n                            <p>12 × 9 + 3 = <span class="text-amber-400 font-bold">111</span></p>\n                            <p>123 × 9 + 4 = <span class="text-amber-400 font-bold">1111</span></p>\n                            <p>1234 × 9 + 5 = <span class="text-amber-400 font-bold">11111</span></p>\n                            <p>12345 × 9 + 6 = <span class="text-amber-400 font-bold">111111</span></p>\n                        </div>\n                        <p class="text-[11px] text-slate-400 font-sans mt-2">Each step adds one more 1 to the repunit answer!</p>\n                    </div>\n                </div>\n                <div class="p-3 bg-indigo-950/40 border border-indigo-500/30 rounded-lg text-xs text-indigo-200">\n                    <strong>Grid Product Law:</strong> Between two numbers with constant sum <em>S</em> (e.g. 10 + 10 = 20 vs 1 + 19 = 20), product is maximized when numbers are equal: <em>10 × 10 = 100 > 1 × 19 = 19</em>.\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_15', 'checkpoints': [{'question': 'Following the repunit pattern, what is the value of 1,111,111 × 1,111,111?', 'options': ['1234567654321', '123456787654321', '12345654321', '1111111111111'], 'correct': 0, 'explanation': 'Since there are 7 ones, the product peaks at 7: 1234567654321.'}, {'question': 'What is 123,456 × 9 + 7?', 'options': ['1,111,111', '1,111,110', '111,111', '11,111,111'], 'correct': 0, 'explanation': 'Following the 9s staircase pattern, 123,456 × 9 + 7 produces seven 1s: 1,111,111.'}]}, {'id': 16, 'title': 'Algebraic Products', 'tag': 'Let Us Solve Final Review • Algebraic Relationships & Adjacent Products', 'lecture': "In our final synthesis of The Dairy Farm, we bridge arithmetic and algebra! Suppose you are told that 67 times 67 equals 4,489. Can you compute 67 times 68 in less than five seconds without writing down a long multiplication? Yes! Observe that 68 is simply 67 plus 1. Therefore, 67 times 68 equals 67 times 67 plus 67! We simply add 67 to 4,489: 4,489 plus 67 equals 4,556! What if you needed 67 times 66? Subtract 67 from 4,489 to get 4,422! This algebraic rule states that n times n plus 1 equals n squared plus n. Next, consider the financial ledger of the dairy village's Women's Football Tournament. 16 teams participate with 18 players each, giving 16 times 18 equals 288 registered players. The organizers sold 450 spectator tickets at 65 rupees each. 450 times 65: 450 times 60 is 27,000, and 450 times 5 is 2,250, totaling 29,250 rupees in ticket revenue. After paying 12,000 rupees for stadium lights and field preparation, the net surplus is 17,250 rupees! Multiplication equips us to model complex events, manage enterprise finances, and see the beauty of algebra in everyday life.", 'theory_html': '\n            <div class="space-y-4 text-slate-200">\n                <p class="text-base leading-relaxed">\n                    Algebraic relationships connect consecutive products, while multi-step budgeting orchestrates community events:\n                </p>\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-teal-500/30">\n                        <h4 class="font-bold text-teal-400 mb-2 flex items-center gap-1.5 font-mono">\n                            <span>⚡</span> Adjacent Square Product Rule\n                        </h4>\n                        <p class="text-slate-300 mb-2">Given that <span class="font-mono text-amber-300 font-bold">67 × 67 = 4,489</span>:</p>\n                        <div class="space-y-2 font-mono bg-slate-900/60 p-3 rounded-lg text-slate-200">\n                            <p>• 67 × 68 = 67 × (67 + 1)</p>\n                            <p>&nbsp; = (67 × 67) + 67</p>\n                            <p>&nbsp; = 4,489 + 67 = <span class="text-emerald-400 font-bold">4,556</span></p>\n                            <div class="border-t border-slate-700 pt-1"></div>\n                            <p>• 67 × 66 = 67 × (67 - 1)</p>\n                            <p>&nbsp; = 4,489 - 67 = <span class="text-cyan-400 font-bold">4,422</span></p>\n                        </div>\n                    </div>\n                    <div class="bg-slate-800/80 p-4 rounded-xl border border-indigo-500/30">\n                        <h4 class="font-bold text-indigo-400 mb-2 flex items-center gap-1.5">\n                            <span>⚽</span> Women\'s Football Tournament Ledger\n                        </h4>\n                        <div class="space-y-1.5 text-slate-300">\n                            <p>• <strong>Athletes:</strong> 16 teams × 18 players = <strong>288 players</strong></p>\n                            <p>• <strong>Ticket Revenue:</strong> 450 tickets × ₹ 65/ticket</p>\n                            <p class="font-mono pl-3 text-slate-400">= (450 × 60) + (450 × 5) = ₹ 27,000 + ₹ 2,250 = ₹ 29,250</p>\n                            <p>• <strong>Expenses:</strong> Ground lighting & logistics = <strong>₹ 12,000</strong></p>\n                            <p class="font-mono text-emerald-300 font-bold pt-1 border-t border-slate-700">Net Surplus = ₹ 29,250 - ₹ 12,000 = ₹ 17,250</p>\n                        </div>\n                    </div>\n                </div>\n                <div class="p-3 bg-emerald-950/40 border border-emerald-500/30 rounded-lg text-xs text-emerald-200">\n                    <strong>Algebraic Principle:</strong> <em>n × (n + 1) = n² + n</em> and <em>n × (n - 1) = n² - n</em>. Understanding algebraic structure eliminates repetitive computation!\n                </div>\n            </div>\n        ', 'simulator_id': 'sim_slide_16', 'checkpoints': [{'question': 'If 45 × 45 = 2,025, what is 45 × 46?', 'options': ['2,025 + 45 = 2,070', '2,025 + 46 = 2,071', '2,025 + 1 = 2,026', '2,025 × 2 = 4,050'], 'correct': 0, 'explanation': '45 × 46 = 45 × (45 + 1) = (45 × 45) + 45 = 2,025 + 45 = 2,070.'}, {'question': 'If 50 × 50 = 2,500, what is 50 × 49?', 'options': ['2,500 - 50 = 2,450', '2,500 - 49 = 2,451', '2,500 - 1 = 2,499', '2,400'], 'correct': 0, 'explanation': '50 × 49 = 50 × (50 - 1) = (50 × 50) - 50 = 2,500 - 50 = 2,450.'}]}, {'id': 17, 'title': 'Challenge 1', 'tag': 'Mastery Challenge 1 • Fundamentals of Grouping & Mental Multiplication', 'questions': [{'id': 1, 'question': 'If ◯ × ◯ = 64 and ◯ × △ = 72, what is the value of △?', 'options': ['9', '8', '7', '6'], 'correct': 0, 'solution_html': '<p>Since ◯ × ◯ = 64 and 8 × 8 = 64, ◯ = 8.<br>Then 8 × △ = 72 implies △ = 72 ÷ 8 = <strong>9</strong>.</p>'}, {'id': 2, 'question': 'A dairy farm packs 6 crates of buttermilk pouches. Each crate has 7 rows of 8 pouches. How many pouches are there in total?', 'options': ['336 pouches', '288 pouches', '312 pouches', '384 pouches'], 'correct': 0, 'solution_html': '<p>Each crate holds 7 × 8 = 56 pouches.<br>For 6 crates: 6 × 56 = 6 × (50 + 6) = 300 + 36 = <strong>336 pouches</strong>.</p>'}, {'id': 3, 'question': 'Which property states that 25 × 19 = 19 × 25?', 'options': ['Commutative Property of Multiplication', 'Associative Property of Multiplication', 'Distributive Property of Multiplication', 'Zero Property of Multiplication'], 'correct': 0, 'solution_html': '<p>The <strong>Commutative Property</strong> states that changing the order of the factors does not change the product (a × b = b × a).</p>'}, {'id': 4, 'question': 'What is the fastest way to evaluate 25 × 37 × 4?', 'options': ['(25 × 4) × 37 = 100 × 37 = 3,700', '(25 × 37) × 4 = 925 × 4 = 3,700', '25 × (37 + 4) = 25 × 41 = 1,025', '37 × (25 ÷ 4)'], 'correct': 0, 'solution_html': '<p>Using the Commutative and Associative properties: (25 × 4) × 37 = 100 × 37 = <strong>3,700</strong>.</p>'}, {'id': 5, 'question': 'Evaluate 185 × 0 × 34:', 'options': ['0', '185', '34', '6,290'], 'correct': 0, 'solution_html': '<p>By the Zero Property of Multiplication, any product with a factor of zero equals <strong>0</strong>.</p>'}, {'id': 6, 'question': 'What is the product of 450 × 800?', 'options': ['360,000', '36,000', '3,600,000', '3,600'], 'correct': 0, 'solution_html': '<p>Multiply non-zero digits: 45 × 8 = 360.<br>Count trailing zeros: one in 450, two in 800 (total 3 zeros).<br>Append 3 zeros to 360: <strong>360,000</strong>.</p>'}, {'id': 7, 'question': 'If a dairy cow drinks 48 litres of water each day, how many litres does she drink in 100 days?', 'options': ['4,800 litres', '480 litres', '48,000 litres', '960 litres'], 'correct': 0, 'solution_html': '<p>48 × 100 shifts the digits two places left and appends two zeros: <strong>4,800 litres</strong>.</p>'}, {'id': 8, 'question': 'Using the halving and doubling method, calculate 32 × 5:', 'options': ['16 × 10 = 160', '64 × 2.5 = 160', '32 × 10 = 320', '16 × 5 = 80'], 'correct': 0, 'solution_html': '<p>Halve 32 to 16, double 5 to 10.<br>16 × 10 = <strong>160</strong>.</p>'}, {'id': 9, 'question': 'What is 44 × 25 using the double halving strategy?', 'options': ['(44 ÷ 4) × (25 × 4) = 11 × 100 = 1,100', '22 × 50 = 1,000', '44 × 100 = 4,400', '11 × 25 = 275'], 'correct': 0, 'solution_html': '<p>Divide 44 by 4 to get 11; multiply 25 by 4 to get 100.<br>11 × 100 = <strong>1,100</strong>.</p>'}, {'id': 10, 'question': 'Which partition represents 28 × 7 correctly?', 'options': ['(20 × 7) + (8 × 7) = 140 + 56 = 196', '(20 × 7) × (8 × 7)', '(28 × 10) - (28 × 7)', '(20 + 7) × (8 + 7)'], 'correct': 0, 'solution_html': '<p>28 = 20 + 8. (20 × 7) + (8 × 7) = 140 + 56 = <strong>196</strong>.</p>'}]}, {'id': 18, 'title': 'Challenge 2', 'tag': 'Mastery Challenge 2 • Compensation, Real-World Problems & Area Models', 'questions': [{'id': 11, 'question': 'Using the compensation strategy, what is 7 × 39?', 'options': ['(7 × 40) - 7 = 280 - 7 = 273', '(7 × 30) + 9 = 210 + 9 = 219', '(7 × 40) + 7 = 287', '280 - 39 = 241'], 'correct': 0, 'solution_html': '<p>39 = 40 - 1. 7 × 39 = (7 × 40) - (7 × 1) = 280 - 7 = <strong>273</strong>.</p>'}, {'id': 12, 'question': 'Calculate 9 × 51 using the under-counting adjustment method:', 'options': ['(9 × 50) + 9 = 450 + 9 = 459', '(9 × 50) - 9 = 450 - 9 = 441', '(9 × 60) - 9 = 531', '450 + 51 = 501'], 'correct': 0, 'solution_html': '<p>51 = 50 + 1. 9 × 51 = (9 × 50) + (9 × 1) = 450 + 9 = <strong>459</strong>.</p>'}, {'id': 13, 'question': 'In a village auditorium, there are 26 rows of chairs with 19 chairs in each row. How many chairs are in the auditorium?', 'options': ['494 chairs', '484 chairs', '514 chairs', '464 chairs'], 'correct': 0, 'solution_html': '<p>26 × 19 = 26 × (20 - 1) = (26 × 20) - 26 = 520 - 26 = <strong>494 chairs</strong>.</p>'}, {'id': 14, 'question': 'A dairy herd of 16 cows produces 15 litres of milk per cow every day. What is the total milk produced in 10 days?', 'options': ['2,400 litres', '2,200 litres', '2,600 litres', '1,800 litres'], 'correct': 0, 'solution_html': '<p>Daily milk = 16 × 15 = (16 ÷ 2) × (15 × 2) = 8 × 30 = 240 litres.<br>In 10 days = 240 × 10 = <strong>2,400 litres</strong>.</p>'}, {'id': 15, 'question': 'A tailor needs 2 m 30 cm of fabric for 1 uniform kurta. How much fabric is needed for 6 kurtas?', 'options': ['13 m 80 cm', '12 m 80 cm', '14 m 20 cm', '13 m 30 cm'], 'correct': 0, 'solution_html': '<p>Metres: 6 × 2 m = 12 m.<br>Centimetres: 6 × 30 cm = 180 cm = 1 m 80 cm.<br>Total = 12 m + 1 m 80 cm = <strong>13 m 80 cm</strong>.</p>'}, {'id': 16, 'question': 'A dairy household produces 400 g of organic kitchen waste daily. How much waste is generated in a 30-day month?', 'options': ['12,000 g (12 kg)', '1,200 g', '120,000 g', '10,000 g'], 'correct': 0, 'solution_html': '<p>400 × 30 = 12,000 g = <strong>12 kg</strong>.</p>'}, {'id': 17, 'question': 'A family makes 30 bags of organic compost at home. If buying commercial compost costs ₹ 110 per bag, how much money does the family save?', 'options': ['₹ 3,300', '₹ 3,000', '₹ 3,600', '₹ 2,700'], 'correct': 0, 'solution_html': '<p>Savings = 30 × ₹ 110 = 3 × 11 × 100 = 33 × 100 = <strong>₹ 3,300</strong>.</p>'}, {'id': 18, 'question': 'In the expanded box multiplication of 53 × 27, what is the partial product of the tens by tens cell (50 × 20)?', 'options': ['1,000', '100', '700', '350'], 'correct': 0, 'solution_html': '<p>50 × 20 = (5 × 2) × (10 × 10) = 10 × 100 = <strong>1,000</strong>.</p>'}, {'id': 19, 'question': 'What is the total product of 53 × 27 calculated via all 4 partial products?', 'options': ['1,431', '1,351', '1,451', '1,381'], 'correct': 0, 'solution_html': '<p>Partial products:<br>50 × 20 = 1,000<br>3 × 20 = 60<br>50 × 7 = 350<br>3 × 7 = 21<br>Sum = 1,000 + 60 + 350 + 21 = <strong>1,431</strong>.</p>'}, {'id': 20, 'question': "What is 74 × 8 using Nida's expanded method?", 'options': ['(70 × 8) + (4 × 8) = 560 + 32 = 592', '(70 × 8) + (4 × 8) = 540 + 32 = 572', '560 - 32 = 528', '70 × 32 = 2,240'], 'correct': 0, 'solution_html': '<p>74 = 70 + 4. (70 × 8) + (4 × 8) = 560 + 32 = <strong>592</strong>.</p>'}]}, {'id': 19, 'title': 'Challenge 3', 'tag': 'Mastery Challenge 3 • Sports Stats, Column Algorithms & Error Analysis', 'questions': [{'id': 21, 'question': 'In a cricket match, a batter hits 16 fours, 5 sixes, and runs 24 singles. What is the total score?', 'options': ['118 runs', '112 runs', '124 runs', '108 runs'], 'correct': 0, 'solution_html': '<p>Fours: 16 × 4 = 64 runs.<br>Sixes: 5 × 6 = 30 runs.<br>Singles: 24 × 1 = 24 runs.<br>Total = 64 + 30 + 24 = <strong>118 runs</strong>.</p>'}, {'id': 22, 'question': 'A cinema theatre has 32 rows with 45 seats in each row. How many seats are there in total?', 'options': ['1,440 seats', '1,380 seats', '1,520 seats', '1,280 seats'], 'correct': 0, 'solution_html': '<p>Using doubling and halving: 32 × 45 = (32 ÷ 2) × (45 × 2) = 16 × 90 = <strong>1,440 seats</strong>.</p>'}, {'id': 23, 'question': 'A dairy cooperative purchases 60 bags of mineral feed at ₹ 750 each. What is the total expenditure?', 'options': ['₹ 45,000', '₹ 42,000', '₹ 48,000', '₹ 40,000'], 'correct': 0, 'solution_html': '<p>60 × 750 = 6 × 75 × 100 = 450 × 100 = <strong>₹ 45,000</strong>.</p>'}, {'id': 24, 'question': 'In the standard column multiplication 362 × 14, what is the first partial product (362 × 4)?', 'options': ['1,448', '1,428', '1,488', '1,348'], 'correct': 0, 'solution_html': '<p>362 × 4 = (300 × 4) + (60 × 4) + (2 × 4) = 1,200 + 240 + 8 = <strong>1,448</strong>.</p>'}, {'id': 25, 'question': 'What is the second partial product in 362 × 14?', 'options': ['3,620 (multiplying by 1 ten)', '362 (multiplying by 1)', '36,200', '7,240'], 'correct': 0, 'solution_html': '<p>The digit 1 is in the tens place (value 10). 362 × 10 = <strong>3,620</strong>.</p>'}, {'id': 26, 'question': 'What is the final product of 362 × 14?', 'options': ['5,068', '4,968', '5,168', '4,868'], 'correct': 0, 'solution_html': '<p>Sum of partial products: 1,448 + 3,620 = <strong>5,068</strong>.</p>'}, {'id': 27, 'question': 'In multiplying 48 × 32, a student writes partial products 96 and 144, getting 240. What was the blunder?', 'options': ['Forgot the zero placeholder in the second line (wrote 144 instead of 1,440)', 'Multiplied 48 × 2 incorrectly', 'Subtracted instead of adding', 'Added 48 + 32'], 'correct': 0, 'solution_html': '<p>The digit 3 in 32 is 30. 48 × 30 = 1,440. Without the zero, the student added 96 + 144 = 240 instead of 96 + 1,440 = <strong>1,536</strong>.</p>'}, {'id': 28, 'question': 'When multiplying 56 × 4, a student computes (5 + 2) × 4 = 28 and writes 284 instead of (5 × 4) + 2 = 22. What is this error called?', 'options': ['Premature Carry Addition', 'Missing Zero Trap', 'Commutative Inversion', 'Truncation Error'], 'correct': 0, 'solution_html': '<p>This is <strong>Premature Carry Addition</strong>: adding the carried 2 to the tens digit before multiplying by 4, instead of multiplying first and then adding the carry (56 × 4 = 224).</p>'}, {'id': 29, 'question': 'A milk tanker delivers 725 litres to 18 booths. What is the total milk delivered?', 'options': ['13,050 litres', '12,950 litres', '13,150 litres', '11,850 litres'], 'correct': 0, 'solution_html': '<p>725 × 18 = 725 × (20 - 2) = 14,500 - 1,450 = <strong>13,050 litres</strong>.</p>'}, {'id': 30, 'question': 'What is the product of 425 × 106?', 'options': ['45,050', '44,950', '45,150', '42,500'], 'correct': 0, 'solution_html': '<p>425 × 106 = 425 × (100 + 6) = (425 × 100) + (425 × 6) = 42,500 + 2,550 = <strong>45,050</strong>.</p>'}]}, {'id': 20, 'title': 'Challenge 4', 'tag': 'Mastery Challenge 4 • Derivative Facts, Growth Puzzles & Algebraic Patterns', 'questions': [{'id': 31, 'question': 'Given that 18 × 24 = 432, what is 18 × 48 without long multiplication?', 'options': ['432 × 2 = 864', '432 + 24 = 456', '432 + 48 = 480', '432 ÷ 2 = 216'], 'correct': 0, 'solution_html': '<p>48 is double 24. Since one factor is doubled while the other stays 18, the product doubles: 432 × 2 = <strong>864</strong>.</p>'}, {'id': 32, 'question': 'Given 18 × 24 = 432, what is 18 × 25?', 'options': ['432 + 18 = 450', '432 + 24 = 456', '432 + 25 = 457', '432 × 2 = 864'], 'correct': 0, 'solution_html': '<p>18 × 25 is one more group of 18 than 18 × 24. 432 + 18 = <strong>450</strong>.</p>'}, {'id': 33, 'question': 'Calculate 72 × 125 using the fractional shortcut:', 'options': ['9,000', '8,500', '9,200', '7,200'], 'correct': 0, 'solution_html': '<p>125 = 1,000 ÷ 8. 72 × 125 = (72 ÷ 8) × 1,000 = 9 × 1,000 = <strong>9,000</strong>.</p>'}, {'id': 34, 'question': "In the King's Reward puzzle, if Choice B doubles starting from 2 on Day 1, how many coins are received on Day 7?", 'options': ['128 coins', '64 coins', '256 coins', '14 coins'], 'correct': 0, 'solution_html': '<p>Day 1 = 2; Day 2 = 4; Day 3 = 8; Day 4 = 16; Day 5 = 32; Day 6 = 64; Day 7 = <strong>128 coins</strong>.</p>'}, {'id': 35, 'question': 'In Choice C (multiplying by 5 each day starting with 1 on Day 1), how many coins are received on Day 6?', 'options': ['3,125 coins', '625 coins', '15,625 coins', '1,250 coins'], 'correct': 0, 'solution_html': '<p>Day 1 = 1; Day 2 = 5; Day 3 = 25; Day 4 = 125; Day 5 = 625; Day 6 = 625 × 5 = <strong>3,125 coins</strong>.</p>'}, {'id': 36, 'question': 'What is the value of the repunit square 1,111 × 1,111?', 'options': ['1,234,321', '1,234,543', '1,233,321', '1,111,111'], 'correct': 0, 'solution_html': '<p>There are 4 ones in the factor, so digits climb symmetrically up to 4 and back down: <strong>1,234,321</strong>.</p>'}, {'id': 37, 'question': 'Following the 9s pattern, what is 1,234 × 9 + 5?', 'options': ['11,111', '1,111', '111,111', '11,110'], 'correct': 0, 'solution_html': '<p>The pattern produces repunits: 1 × 9 + 2 = 11; 12 × 9 + 3 = 111; 123 × 9 + 4 = 1,111; 1,234 × 9 + 5 = <strong>11,111</strong>.</p>'}, {'id': 38, 'question': 'If 75 × 75 = 5,625, what is 75 × 76?', 'options': ['5,625 + 75 = 5,700', '5,625 + 76 = 5,701', '5,625 + 1 = 5,626', '5,725'], 'correct': 0, 'solution_html': '<p>75 × 76 = 75 × (75 + 1) = (75 × 75) + 75 = 5,625 + 75 = <strong>5,700</strong>.</p>'}, {'id': 39, 'question': 'If 80 × 80 = 6,400, what is 80 × 79?', 'options': ['6,400 - 80 = 6,320', '6,400 - 79 = 6,321', '6,400 - 1 = 6,399', '6,240'], 'correct': 0, 'solution_html': '<p>80 × 79 = 80 × (80 - 1) = (80 × 80) - 80 = 6,400 - 80 = <strong>6,320</strong>.</p>'}, {'id': 40, 'question': 'In a dairy football league, 18 teams register with 15 players each. If 520 tickets are sold at ₹ 50 each and expenses are ₹ 9,000, what is the net surplus?', 'options': ['₹ 17,000', '₹ 16,000', '₹ 18,000', '₹ 15,000'], 'correct': 0, 'solution_html': '<p>Ticket revenue = 520 × ₹ 50 = ₹ 26,000.<br>Expenses = ₹ 9,000.<br>Net surplus = ₹ 26,000 - ₹ 9,000 = <strong>₹ 17,000</strong>.</p>'}]}]
